contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint ticketAmount) public payable {
        // Only call c.play() if we can send exactly TICKET_AMOUNT Ether.
        require(ticketAmount == 10);
        require(address(this).balance >= ticketAmount);

        // Read pre-call state.
        uint bankBefore = address(c.bank()).balance; // The bank address is public; its balance is observable.
        uint potBefore = c.pot();
        uint cBalanceBefore = address(c).balance;

        // Make the deciding call. This is a top-level statement.
        c.play{value: ticketAmount}();

        // Read post-call state.
        uint bankAfter = address(c.bank()).balance;
        uint potAfter = c.pot();
        uint cBalanceAfter = address(c).balance;

        // General rule:
        // 1) The contract cannot gain more than the ticket minus the fee (it cannot keep the fee).
        // 2) If the pot did not reset to zero, it must equal the previous pot plus the ticket.
        // 3) If the pot reset to zero, the bank's balance must have increased by the fee.
        assert(
            cBalanceAfter <= cBalanceBefore + ticketAmount - 1 &&
            (potAfter == potBefore + ticketAmount && bankAfter == bankBefore ||
             potAfter == 0 && bankAfter == bankBefore + 1)
        );
    }

    receive() external payable {}
}

